import{c as e,Q as r,j as a,m as n}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"SportIdent cards","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/sportident-cards.md","filePath":"user/reference/sportident-cards.md"}'),o={name:"user/reference/sportident-cards.md"};function s(d,t,i,h,c,l){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="sportident-cards" tabindex="-1">SportIdent cards <a class="header-anchor" href="#sportident-cards" aria-label="Permalink to &quot;SportIdent cards&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators who want to know what Manager does with a card, and what can go wrong with one.</p><p>Which cards Manager reads, what it takes from them, and the problems cards cause on the day.</p><h2 id="which-cards-manager-reads" tabindex="-1">Which cards Manager reads <a class="header-anchor" href="#which-cards-manager-reads" aria-label="Permalink to &quot;Which cards Manager reads&quot;">​</a></h2><p>Manager reads every SportIdent card a download station can read:</p><table tabindex="0"><thead><tr><th>Card</th><th>Card numbers</th><th>Punches it holds</th></tr></thead><tbody><tr><td><strong>SI Card 5</strong> (and 5R, 5U)</td><td>1 to 465,000 in four blocks, and 3,000,000 to 3,999,999</td><td>30 with times; a 31st to 36th keep only the control code</td></tr><tr><td><strong>SI Card 6</strong></td><td>500,000 to 999,999</td><td>64</td></tr><tr><td><strong>SI Card 8</strong></td><td>2,000,000 to 2,799,999</td><td>30</td></tr><tr><td><strong>ComCard Up</strong></td><td>2,800,000 to 2,999,999</td><td>30</td></tr><tr><td><strong>SI Card 9</strong></td><td>1,000,000 to 1,999,999</td><td>50</td></tr><tr><td><strong>pCard</strong></td><td>4,000,000 to 4,999,999</td><td>20</td></tr><tr><td><strong>tCard</strong></td><td>6,000,000 to 6,999,999</td><td>25</td></tr><tr><td><strong>SI Card 10</strong></td><td>7,000,000 to 7,999,999</td><td>128</td></tr><tr><td><strong>SIAC</strong></td><td>8,000,000 to 8,999,999</td><td>128</td></tr><tr><td><strong>SI Card 11</strong></td><td>9,000,000 to 9,999,999</td><td>128</td></tr></tbody></table><p>An <strong>fCard</strong> (14,000,000 to 14,999,999) can&#39;t be downloaded; SportIdent&#39;s own software can&#39;t read one either.</p><p>Manager also reads <strong>EMIT</strong> cards, for an event set up for EMIT (<strong>Settings → Event defaults → Timing card system</strong>, and each event&#39;s own setting).</p><h2 id="what-manager-takes-from-a-card" tabindex="-1">What Manager takes from a card <a class="header-anchor" href="#what-manager-takes-from-a-card" aria-label="Permalink to &quot;What Manager takes from a card&quot;">​</a></h2><p>A download reads the card&#39;s number, its <strong>check</strong>, <strong>start</strong> and <strong>finish</strong> punches, and every control punch in order, each with its control code and time. Manager then matches the card to the competitor holding that number, scores the punches against their course, and works out their result. See <a href="./../running-the-event/card-download">Card download</a> and <a href="./status-and-race-time">Status and race time rules</a>.</p><p>Reading a card&#39;s number without downloading it, for example to fill in <strong>Card number</strong> at the registration desk, reads only the number. See <a href="./../running-the-event/late-entries#reading-the-card-number-off-the-card">Late entries and the registration desk</a>.</p><p>Every download is also kept as a file of its own, so a card read is never only in one place. See <a href="./backup-and-restore#card-downloads-are-always-kept-twice">Card downloads are always kept twice</a>.</p><h3 id="si-card-5-s-twelve-hour-clock" tabindex="-1">SI Card 5&#39;s twelve-hour clock <a class="header-anchor" href="#si-card-5-s-twelve-hour-clock" aria-label="Permalink to &quot;SI Card 5&#39;s twelve-hour clock&quot;">​</a></h3><p>An SI Card 5 stores its times on a 12-hour clock, without AM or PM. Manager works out which half of the day each punch belongs to from when the card was read, so a morning race and an afternoon one both come out right with no setting to change. An SI Card 5 also records no code for its start, finish and check punches, only their times.</p><h2 id="cards-without-an-owner" tabindex="-1">Cards without an owner <a class="header-anchor" href="#cards-without-an-owner" aria-label="Permalink to &quot;Cards without an owner&quot;">​</a></h2><p>A card nobody in the event holds:</p><ul><li><strong>At download</strong>, the result can&#39;t land on anyone. Assign the download to the right competitor, or add a competitor for the card, from <a href="./../running-the-event/card-download#fast-fixes-right-after-a-download">Card downloads</a>. At a <a href="./../event-setup/low-key-events">low-key event</a>, Manager can enter it for you.</li><li><strong>On the radio</strong>, its punches show as <strong>Unknown</strong>. Click to add a competitor for it. See <a href="./../running-the-event/radio-punches#unknown-cards">Unknown cards</a>.</li><li><strong>In a station&#39;s memory</strong>, it&#39;s listed under <strong>Unmatched cards</strong>. See <a href="./../running-the-event/station-memory#cards-nobody-is-entered-on">Station memory</a>.</li></ul><p>If the card is in the <a href="./competitor-registry">Competitor Registry</a>, Manager suggests the person it belongs to.</p><h2 id="hire-cards-and-shared-cards" tabindex="-1">Hire cards and shared cards <a class="header-anchor" href="#hire-cards-and-shared-cards" aria-label="Permalink to &quot;Hire cards and shared cards&quot;">​</a></h2><ul><li><strong>Hire cards</strong> go in <strong>Settings → Hire card registry</strong>. A competitor holding one is marked as being on a hire card, and the download desk is reminded to collect it. See <a href="./../running-the-event/hire-items">Hire items</a>.</li><li><strong>Two people can share a card</strong> if they run at different times. Manager flags the number as <strong>Duplicate</strong> on the Competitors list, because if both are out at once a download can land on the wrong one. See <a href="./../event-setup/competitors-clubs-teams#card-numbers">Card numbers</a>.</li><li>A card&#39;s number is never used to recognise a person between events, because hire cards change hands.</li></ul><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What&#39;s happening</th><th>What to do</th></tr></thead><tbody><tr><td><strong>The card has last week&#39;s punches on it</strong></td><td>The runner didn&#39;t clear it at the start. The old punches come first, so their splits are wrong, and an old <strong>Check</strong> or <strong>Finish</strong> punch can set the wrong start or finish.</td><td>Manager leaves out punches it can tell came from another outing, such as ones stamped after the card&#39;s own finish punch. For anything it can&#39;t tell, exclude the old punches on the competitor&#39;s <strong>Overrides</strong> tab. See <a href="./../running-the-event/resolving-issues#competitor-results">Resolving issues on the day</a>.</td></tr><tr><td><strong>The card is full</strong></td><td>Every punch slot is used, so later punches weren&#39;t stored. An SI Card 8 holds 30 and a pCard 20, so a long course or a score event can fill one.</td><td>Use the radio punches or the control units&#39; memories for the missing controls, and override the punches on the <strong>Overrides</strong> tab. Give that runner a card that holds more next time.</td></tr><tr><td><strong>The read fails, or comes back incomplete</strong></td><td>The card was taken off the station too early, or the station lost contact.</td><td>Put the card back on the station and leave it there until the reader confirms.</td></tr><tr><td><strong>All the punches at one control are out by the same amount</strong></td><td>That control unit&#39;s clock was wrong.</td><td>Set a <strong>Time Offset</strong> on the control. See <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>. Check every unit&#39;s clock before the event with <a href="./../running-the-event/station-memory#the-station-clock">Station memory</a>.</td></tr><tr><td><strong>The card isn&#39;t recognised at all</strong></td><td>Its number is outside every range above, or it&#39;s an fCard.</td><td>Read it again. If it still fails, type the run in as a <a href="./../running-the-event/card-download#manual-downloads">manual download</a>.</td></tr><tr><td><strong>A runner lost their card</strong></td><td>There&#39;s nothing to download.</td><td>Type the run in as a <a href="./../running-the-event/card-download#manual-downloads">manual download</a>, from the radio punches or the units&#39; memories.</td></tr></tbody></table><h2 id="looking-after-cards" tabindex="-1">Looking after cards <a class="header-anchor" href="#looking-after-cards" aria-label="Permalink to &quot;Looking after cards&quot;">​</a></h2><p>A SIAC has a battery for contactless punching, and it runs down with use. Check SIAC batteries before a big event with SportIdent&#39;s own software. Keep every card clean and dry.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/card-download">Card download</a></li><li><a href="./../running-the-event/station-memory">Station memory</a></li><li><a href="./station-configuration">Station configuration</a></li><li><a href="./../running-the-event/hire-items">Hire items</a></li><li><a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a></li><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a></li></ul>',26)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
